// ===== DISCOVERIES SYNC CONFIG =====
const LOOKBACK_DAYS = 60;     // refresh outcomes this far back; future meetings always included
const BACKFILL_START = '';    // '2026-01-01' once, then ''
const DISCOVERY_ACTIVITY_TYPES = ['Discovery'];
const DISCOVERY_TITLE_REGEX = '(discovery|erstgespr|kennenlern)';

const DAY = 86400000; const now = Date.now();
let chunks = [];
if (BACKFILL_START) {
  let cur = Date.parse(BACKFILL_START);
  while (cur < now) { const d = new Date(cur); const nx = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1);
    chunks.push({ fromMs: cur, toMs: Math.min(nx, now) }); cur = nx; }
} else { chunks = [{ fromMs: now - LOOKBACK_DAYS * DAY, toMs: now }]; }

return chunks.map(c => ({ json: { fromMs: c.fromMs, toMs: BACKFILL_START ? c.toMs : c.toMs + 365 * DAY,
  DISCOVERY_ACTIVITY_TYPES, DISCOVERY_TITLE_REGEX } }));

const cfg = $('Config').all()[0].json;
const rx = new RegExp(cfg.DISCOVERY_TITLE_REGEX, 'i');
const types = cfg.DISCOVERY_ACTIVITY_TYPES.map(t => String(t).toLowerCase());
const meetings = {};
for (const it of $input.all()) for (const m of (it.json.results || [])) {
  const p = m.properties || {};
  const isDisc = types.includes(String(p.hs_activity_type || '').trim().toLowerCase()) || rx.test(String(p.hs_meeting_title || ''));
  if (isDisc) meetings[m.id] = m;
}
const ids = Object.keys(meetings);
const out = [{ json: { state: true, count: ids.length } }];
for (const to of ['companies','contacts'])
  for (let i = 0; i < ids.length; i += 100)
    out.push({ json: { to, url: 'https://api.hubapi.com/crm/v4/associations/meetings/' + to + '/batch/read',
      body: { inputs: ids.slice(i, i + 100).map(id => ({ id })) } } });
return out;

const pi = it => it.pairedItem ? (typeof it.pairedItem === 'number' ? it.pairedItem : it.pairedItem.item) : 0;

const reqs = $('Filter + Build Assoc').all();
const mToCo = {}, mToCt = {};
for (const it of $input.all()) {
  const meta = reqs[pi(it)] ? reqs[pi(it)].json : {};
  if (!meta.to) continue;
  for (const r of (it.json.results || [])) {
    const f = String(r.from && r.from.id);
    if (meta.to === 'companies') mToCo[f] = String((r.to || [])[0] ? r.to[0].toObjectId : '');
    else mToCt[f] = (r.to || []).map(t => String(t.toObjectId));
  }
}
const cids = new Set(); for (const arr of Object.values(mToCt)) for (const c of arr) cids.add(c);
const ids = [...cids];
const out = [{ json: { mToCo, mToCt } }];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { body: { inputs: ids.slice(i, i + 100).map(id => ({ id })),
    properties: ['firstname','lastname','jobtitle','associatedcompanyid','first_conversion_event_name','first_conversion_date','recent_conversion_event_name','recent_conversion_date'] } } });
return out;

const contacts = {};
for (const it of $input.all()) for (const r of ((it.json || {}).results || []))
  { const p = r.properties || {};
    const nm = ((p.firstname||'') + ' ' + (p.lastname||'')).trim();
    const convs = [];
    if (p.first_conversion_event_name && p.first_conversion_date)
      convs.push({ n: p.first_conversion_event_name, d: String(p.first_conversion_date).slice(0, 10) });
    if (p.recent_conversion_event_name && p.recent_conversion_date &&
        p.recent_conversion_event_name !== p.first_conversion_event_name)
      convs.push({ n: p.recent_conversion_event_name, d: String(p.recent_conversion_date).slice(0, 10) });
    contacts[String(r.id)] = { name: p.jobtitle ? nm + ' (' + p.jobtitle + ')' : nm,
      companyId: p.associatedcompanyid || null, convs }; }
const state = $('Build Contact Reads').all()[0].json;
const compIds = new Set(Object.values(state.mToCo).filter(Boolean));
for (const c of Object.values(contacts)) if (c.companyId) compIds.add(String(c.companyId));
const ids = [...compIds];
const out = [{ json: { contacts } }];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { body: { inputs: ids.slice(i, i + 100).map(id => ({ id })), properties: ['name'] } } });
return out;

const esc = v => v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = v => v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v));
const bool = v => v ? 'true' : 'false';

const owners = {};
for (const o of ($('Get Owners').first().json.results || []))
  owners[String(o.id)] = ((o.firstName || '') + ' ' + (o.lastName || '')).trim() || o.email || String(o.id);

const assocState = $('Build Contact Reads').all()[0].json;
const contacts = $('Build Company Reads').all()[0].json.contacts;
const names = {};
for (const it of $('Read Companies').all()) for (const r of ((it.json || {}).results || [])) names[String(r.id)] = (r.properties || {}).name || '';
const aiNotes = {};
for (const it of $input.all()) {
  const content = it.json && it.json.content;
  if (!Array.isArray(content)) continue;
  let t = content.filter(c => c.type === 'text').map(c => c.text).join('');
  try { for (const r of JSON.parse(t.replace(/```json|```/g, '').trim())) aiNotes[String(r.id)] = r; } catch (e) {}
}
const cfg = $('Config').all()[0].json;
const rx = new RegExp(cfg.DISCOVERY_TITLE_REGEX, 'i');
const types = cfg.DISCOVERY_ACTIVITY_TYPES.map(t => String(t).toLowerCase());
const rows = []; const seen = new Set();
const now = Date.now();
for (const it of $('Search Meetings').all()) for (const m of (it.json.results || [])) {
  if (seen.has(m.id)) continue;
  const p = m.properties || {};
  const isDisc = types.includes(String(p.hs_activity_type || '').trim().toLowerCase()) || rx.test(String(p.hs_meeting_title || ''));
  if (!isDisc) continue;
  seen.add(m.id);
  const start = Date.parse(p.hs_meeting_start_time);
  const oc = String(p.hs_meeting_outcome || '').toUpperCase();
  let status;
  if (oc === 'CANCELED') status = 'canceled';
  else if (oc === 'NO_SHOW') status = 'no_show';
  else if (oc === 'RESCHEDULED') status = 'rescheduled';
  else if (oc === 'COMPLETED') status = 'completed';
  else status = (start > now) ? 'upcoming' : 'completed';
  const compId = assocState.mToCo[String(m.id)] ||
    ((assocState.mToCt[String(m.id)] || []).map(c => contacts[c] && contacts[c].companyId).find(Boolean)) || null;
  const ctNames = (assocState.mToCt[String(m.id)] || []).map(c => contacts[c] && contacts[c].name).filter(Boolean).join(', ');
  const kindOf = n => /download|whitepaper|guide|report|checklist|studie|ebook/i.test(n) ? 'download'
    : /event|webinar|einladung|invite|dmexco|omr|konferenz|summit|afterwork|stammtisch/i.test(n) ? 'event'
    : /kontakt|contact|demo|meeting|termin|beratung|sales/i.test(n) ? 'form' : 'form';
  const convParts = [];
  for (const c of (assocState.mToCt[String(m.id)] || [])) {
    const co = contacts[c];
    for (const cv of ((co && co.convs) || [])) convParts.push(kindOf(cv.n) + '|' + cv.d + '|' + String(cv.n).slice(0, 60).replace(/[;|]/g, ' '));
  }
  const conversions = [...new Set(convParts)].join(';') || null;
  const attIds = String(p.hs_attendee_owner_ids || '').split(';').filter(Boolean);
  if (p.hubspot_owner_id) attIds.unshift(String(p.hubspot_owner_id));
  const parts = [...new Set(attIds.map(id => (owners[String(id)] || '').split(' ')[0]).filter(Boolean))].join(', ');
  const ai = aiNotes[String(m.id)] || {};
  rows.push('(' + [num(m.id), num(compId), esc(compId ? names[String(compId)] || '' : ''), esc(ctNames),
    esc(owners[String(p.hubspot_owner_id)] || 'Unknown'),
    esc(p.hs_meeting_start_time ? new Date(start).toISOString() : null),
    esc(p.hs_createdate ? new Date(Date.parse(p.hs_createdate)).toISOString() : null),
    esc(p.hs_activity_type || ''), esc(oc || null), esc(status), esc(parts), esc(ai.outcome || null), esc(ai.todo || null), esc(ai.topic || null), esc(conversions), esc(new Date().toISOString())].join(',') + ')');
}
if (!rows.length) return [{ json: { sql: 'SELECT 1;' } }];
return [{ json: { sql: 'INSERT INTO discoveries (meeting_id,company_id,company_name,contact_name,owner_name,meeting_start,created_at,activity_type,outcome,status,participants,outcome_note,next_todo,topic,conversions,updated_at) VALUES\n' +
  rows.join(',\n') + '\nON CONFLICT (meeting_id) DO UPDATE SET company_id=EXCLUDED.company_id, company_name=EXCLUDED.company_name, contact_name=EXCLUDED.contact_name, owner_name=EXCLUDED.owner_name, meeting_start=EXCLUDED.meeting_start, created_at=EXCLUDED.created_at, activity_type=EXCLUDED.activity_type, outcome=EXCLUDED.outcome, status=EXCLUDED.status, participants=EXCLUDED.participants, outcome_note=COALESCE(EXCLUDED.outcome_note, discoveries.outcome_note), next_todo=EXCLUDED.next_todo, topic=COALESCE(EXCLUDED.topic, discoveries.topic), conversions=EXCLUDED.conversions, updated_at=EXCLUDED.updated_at;' } }];

const cfg = { model: 'claude-sonnet-5' };
const rxCfg = $('Config').all()[0].json;
const rx = new RegExp(rxCfg.DISCOVERY_TITLE_REGEX, 'i');
const types = rxCfg.DISCOVERY_ACTIVITY_TYPES.map(t => String(t).toLowerCase());
const now = Date.now();
const items = [];
const seen = new Set();
for (const it of $('Search Meetings').all()) for (const m of (it.json.results || [])) {
  if (seen.has(m.id)) continue; seen.add(m.id);
  const p = m.properties || {};
  const isDisc = types.includes(String(p.hs_activity_type || '').trim().toLowerCase()) || rx.test(String(p.hs_meeting_title || ''));
  if (!isDisc) continue;
  const upcoming = Date.parse(p.hs_meeting_start_time) > now;
  const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  const notes = (strip(p.hs_internal_meeting_notes) + ' ' + strip(p.hs_meeting_body)).trim().slice(0, 1200);
  if (notes.length > 30) items.push({ id: m.id, kind: upcoming ? 'upcoming' : 'past',
    title: String(p.hs_meeting_title || '').slice(0, 120), notes });
}
if (!items.length) return [{ json: { has: false } }];
const out = [];
for (let i = 0; i < items.length; i += 15) {
  const batch = items.slice(i, i + 15);
  out.push({ json: { has: true, body: { model: cfg.model, max_tokens: 2000, messages: [{ role: 'user', content:
    'You summarize sales discovery meeting notes (German or English) for a compact report table. ' +
    'For kind=past meetings produce: outcome (max 7 words, how it went / what was learned) and todo (max 7 words, next action on our side, or null). ' +
    'For kind=upcoming meetings produce: topic (max 6 words, what the prospect wants to discuss, from the invite/notes; null if unclear). ' +
    'Respond ONLY with a JSON array, no fences: [{"id":"...","outcome":...,"todo":...,"topic":...}]\n\n' + JSON.stringify(batch) } ] } } });
}
return out;
